import React, { useEffect, useState } from 'react';
import { getStats, getUsers } from '../services/adminService';
import { getRequests } from '../services/requestService';
import { toast } from 'react-toastify';
import { FiUsers, FiFileText, FiClock, FiCheckCircle, FiXCircle, FiAlertCircle, FiTrendingUp, FiActivity, FiCalendar, FiRefreshCw, FiFilter, FiSearch, FiSettings, FiShield, FiZap, FiTarget, FiBarChart2, FiPieChart, FiUserX, FiMoreVertical, FiDownload, FiBriefcase, FiAward, FiGitBranch, FiTrendingDown, FiPercent } from 'react-icons/fi';
import { Line, Doughnut, Bar, Pie } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement } from 'chart.js';
import '../../styles/statistics.css';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement);

const Statistics = () => {
  const [stats, setStats] = useState({});
  const [users, setUsers] = useState([]);
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeriod, setFilterPeriod] = useState('all');

  useEffect(() => {
    loadData();
    if (autoRefresh) {
      const intervalId = setInterval(() => {
        loadData();
      }, 30000); // Refresh every 30 seconds
      return () => clearInterval(intervalId);
    }
  }, [autoRefresh]);

  const loadData = async () => {
    try {
      const statsData = await getStats();
      setStats(statsData);
      
      const requestsData = await getRequests();
      setRequests(requestsData);
      
      const usersData = await getUsers();
      setUsers(usersData);
    } catch (error) {
      toast.error('Erreur lors du chargement des statistiques');
    } finally {
      setLoading(false);
    }
  };

  const filteredRequests = requests.filter(req => {
    const matchesSearch = req.reference.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          req.workflowType.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch;
  });

  // Calculate additional statistics
  const calculateStats = () => {
    const totalUsers = users.length;
    const activeUsers = users.filter(u => u.isActive).length;
    const inactiveUsers = totalUsers - activeUsers;
    
    const totalRequests = requests.length;
    const approvedRequests = requests.filter(r => r.status === 'approved').length;
    const rejectedRequests = requests.filter(r => r.status === 'rejected').length;
    const pendingRequests = requests.filter(r => r.status === 'pending').length;
    const inProgressRequests = requests.filter(r => r.status === 'in_progress').length;
    const returnedRequests = requests.filter(r => r.status === 'returned').length;
    
    const adminCount = users.filter(u => u.role === 'admin').length;
    const validatorCount = users.filter(u => u.role === 'validator').length;
    const employeeCount = users.filter(u => u.role === 'employee').length;
    
    const departments = [...new Set(users.map(u => u.department).filter(Boolean))];
    const avgRequestsPerUser = totalUsers > 0 ? (totalRequests / totalUsers).toFixed(2) : 0;
    
    return {
      totalUsers,
      activeUsers,
      inactiveUsers,
      totalRequests,
      approvedRequests,
      rejectedRequests,
      pendingRequests,
      inProgressRequests,
      returnedRequests,
      adminCount,
      validatorCount,
      employeeCount,
      departments,
      avgRequestsPerUser
    };
  };

  const calculatedStats = calculateStats();

  // Chart data
  const monthlyData = () => {
    const monthLabels = ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin', 'Juil', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'];
    const requestsByMonth = new Array(12).fill(0);
    const approvalsByMonth = new Array(12).fill(0);
    
    requests.forEach((request) => {
      if (!request.createdAt) return;
      const monthIndex = new Date(request.createdAt).getMonth();
      if (monthIndex >= 0 && monthIndex < 12) {
        requestsByMonth[monthIndex] += 1;
        if (request.status === 'approved') {
          approvalsByMonth[monthIndex] += 1;
        }
      }
    });

    return {
      labels: monthLabels,
      datasets: [
        {
          label: 'Demandes créées',
          data: requestsByMonth,
          borderColor: 'rgb(59,130,246)',
          backgroundColor: 'rgba(59,130,246,0.2)',
          tension: 0.2,
        },
        {
          label: 'Demandes approuvées',
          data: approvalsByMonth,
          borderColor: 'rgb(16,185,129)',
          backgroundColor: 'rgba(16,185,129,0.2)',
          tension: 0.2,
        }
      ]
    };
  };

  const statusData = {
    labels: ['Approuvées', 'Rejetées', 'En attente', 'En cours', 'Retournées'],
    datasets: [{
      data: [
        calculatedStats.approvedRequests,
        calculatedStats.rejectedRequests,
        calculatedStats.pendingRequests,
        calculatedStats.inProgressRequests,
        calculatedStats.returnedRequests
      ],
      backgroundColor: ['#10b981', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6'],
      borderWidth: 2,
      borderColor: '#ffffff'
    }]
  };

  const roleData = {
    labels: ['Admins', 'Validateurs', 'Employés'],
    datasets: [{
      data: [calculatedStats.adminCount, calculatedStats.validatorCount, calculatedStats.employeeCount],
      backgroundColor: ['#ef4444', '#3b82f6', '#10b981'],
      borderWidth: 2,
      borderColor: '#ffffff'
    }]
  };

  const departmentData = () => {
    const deptCounts = {};
    users.forEach(user => {
      if (user.department) {
        deptCounts[user.department] = (deptCounts[user.department] || 0) + 1;
      }
    });

    return {
      labels: Object.keys(deptCounts),
      datasets: [{
        data: Object.values(deptCounts),
        backgroundColor: [
          '#3b82f6', '#ef4444', '#10b981', '#f59e0b', 
          '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
        ],
        borderWidth: 2,
        borderColor: '#ffffff'
      }]
    };
  };

  const statCards = [
    { title: 'Total Utilisateurs', value: calculatedStats.totalUsers, tone: 'slate', icon: <FiUsers className="w-6 h-6" />, trend: '+12%' },
    { title: 'Utilisateurs Actifs', value: calculatedStats.activeUsers, tone: 'green', icon: <FiShield className="w-6 h-6" />, trend: '+8%' },
    { title: 'Total Demandes', value: calculatedStats.totalRequests, tone: 'blue', icon: <FiFileText className="w-6 h-6" />, trend: '+15%' },
    { title: 'Demandes Approuvées', value: calculatedStats.approvedRequests, tone: 'emerald', icon: <FiCheckCircle className="w-6 h-6" />, trend: '+5%' },
    { title: 'Demandes Rejetées', value: calculatedStats.rejectedRequests, tone: 'red', icon: <FiXCircle className="w-6 h-6" />, trend: '-2%' },
    { title: 'En Attente', value: calculatedStats.pendingRequests, tone: 'amber', icon: <FiClock className="w-6 h-6" />, trend: '+3%' },
    { title: 'En Cours', value: calculatedStats.inProgressRequests, tone: 'blue', icon: <FiActivity className="w-6 h-6" />, trend: '+7%' },
    { title: 'Retournées', value: calculatedStats.returnedRequests, tone: 'purple', icon: <FiAlertCircle className="w-6 h-6" />, trend: '+1%' },
  ];

  const performanceCards = [
    { title: 'Taux d\'Approbation', value: calculatedStats.totalRequests > 0 ? `${((calculatedStats.approvedRequests / calculatedStats.totalRequests) * 100).toFixed(1)}%` : '0%', tone: 'emerald', icon: <FiPercent className="w-6 h-6" /> },
    { title: 'Moyenne/Demande', value: calculatedStats.avgRequestsPerUser, tone: 'blue', icon: <FiBarChart2 className="w-6 h-6" /> },
    { title: 'Départements', value: calculatedStats.departments.length, tone: 'purple', icon: <FiBriefcase className="w-6 h-6" /> },
    { title: 'Admins', value: calculatedStats.adminCount, tone: 'red', icon: <FiAward className="w-6 h-6" /> },
  ];

  return (
    <div className="min-h-screen bg-black text-white overflow-hidden">
      {/* Animated Grid Background */}
      <div className="fixed inset-0 z-0">
        <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/10 via-blue-500/10 to-purple-500/10"></div>
        <svg className="absolute inset-0 w-full h-full" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
              <path d="M 40 0 L 0 0 0 40" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="1"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>
      </div>

      {/* Header */}
      <div className="relative z-10 border-b border-white/10">
        <div className="container mx-auto px-6 py-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-5xl font-black tracking-tight flex items-center gap-4">
                <span className="text-cyan-400">STATS</span>
                <span className="text-white/50">DASHBOARD</span>
              </h1>
              <p className="text-white/30 mt-2 text-lg">System Performance Analytics</p>
            </div>
            <div className="flex items-center gap-4">
              <button
                onClick={() => setAutoRefresh(!autoRefresh)}
                className={`px-6 py-3 border transition-all flex items-center gap-2 font-medium ${
                  autoRefresh 
                    ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50' 
                    : 'bg-white/10 text-white/70 border-white/20'
                }`}
              >
                <FiRefreshCw className={`w-4 h-4 ${autoRefresh ? 'animate-spin' : ''}`} />
                LIVE
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="relative z-10 container mx-auto px-6 py-8">
        {/* Main Metrics Display */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-12">
          {/* Central Large Metric */}
          <div className="lg:col-span-2 bg-gradient-to-br from-cyan-500/20 to-blue-500/20 rounded-3xl p-8 border border-cyan-500/30">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h2 className="text-white/50 text-sm font-medium uppercase tracking-wider mb-2">Total System Activity</h2>
                <div className="flex items-baseline gap-4">
                  <span className="text-7xl font-black text-white">{calculatedStats.totalRequests}</span>
                  <span className="text-cyan-400 text-2xl font-bold">DEMANDS</span>
                </div>
              </div>
              <div className="text-right">
                <div className="text-green-400 text-3xl font-bold">+15%</div>
                <div className="text-white/30 text-sm">vs last month</div>
              </div>
            </div>
            
            {/* Mini Bar Chart */}
            <div className="h-32">
              <div className="flex items-end justify-between h-full gap-2">
                {[65, 45, 80, 55, 70, 85, 60, 75, 90, 65, 80, 95].map((height, i) => (
                  <div
                    key={i}
                    className="flex-1 bg-gradient-to-t from-cyan-500 to-blue-500 rounded-t-lg transition-all duration-500 hover:from-cyan-400 hover:to-blue-400"
                    style={{ height: `${height}%` }}
                  />
                ))}
              </div>
              <div className="flex justify-between mt-2 text-white/30 text-xs">
                {['J', 'F', 'M', 'A', 'M', 'J', 'J', 'A', 'S', 'O', 'N', 'D'].map((month, i) => (
                  <span key={i}>{month}</span>
                ))}
              </div>
            </div>
          </div>

          {/* Side Metrics */}
          <div className="space-y-6">
            <div className="bg-gradient-to-br from-green-500/20 to-emerald-500/20 rounded-2xl p-6 border border-green-500/30">
              <div className="flex items-center justify-between mb-2">
                <span className="text-white/50 text-sm font-medium">APPROVED</span>
                <FiCheckCircle className="w-5 h-5 text-green-400" />
              </div>
              <div className="text-4xl font-black text-white">{calculatedStats.approvedRequests}</div>
              <div className="text-green-400 text-sm mt-1">{calculatedStats.totalRequests > 0 ? `${((calculatedStats.approvedRequests / calculatedStats.totalRequests) * 100).toFixed(1)}%` : '0%'} rate</div>
            </div>

            <div className="bg-gradient-to-br from-orange-500/20 to-amber-500/20 rounded-2xl p-6 border border-orange-500/30">
              <div className="flex items-center justify-between mb-2">
                <span className="text-white/50 text-sm font-medium">PENDING</span>
                <FiClock className="w-5 h-5 text-orange-400" />
              </div>
              <div className="text-4xl font-black text-white">{calculatedStats.pendingRequests}</div>
              <div className="text-orange-400 text-sm mt-1">awaiting review</div>
            </div>

            <div className="bg-gradient-to-br from-purple-500/20 to-pink-500/20 rounded-2xl p-6 border border-purple-500/30">
              <div className="flex items-center justify-between mb-2">
                <span className="text-white/50 text-sm font-medium">USERS</span>
                <FiUsers className="w-5 h-5 text-purple-400" />
              </div>
              <div className="text-4xl font-black text-white">{calculatedStats.totalUsers}</div>
              <div className="text-purple-400 text-sm mt-1">{calculatedStats.activeUsers} active</div>
            </div>
          </div>
        </div>

        {/* Charts Section - Minimal Cards */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-12">
          {/* Status Distribution - Full Width Chart */}
          <div className="bg-white/5 rounded-3xl p-8 border border-white/10">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-2xl font-bold text-white">STATUS BREAKDOWN</h2>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Approved</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-orange-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Pending</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Rejected</span>
                </div>
              </div>
            </div>
            <div className="h-64">
              <Doughnut 
                data={statusData} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      display: false
                    }
                  }
                }}
              />
            </div>
          </div>

          {/* Role Distribution */}
          <div className="bg-white/5 rounded-3xl p-8 border border-white/10">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-2xl font-bold text-white">USER ROLES</h2>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Admins</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Validators</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                  <span className="text-white/50 text-sm">Employees</span>
                </div>
              </div>
            </div>
            <div className="h-64">
              <Pie 
                data={roleData} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      display: false
                    }
                  }
                }}
              />
            </div>
          </div>
        </div>

        {/* Bottom Section - Department Chart */}
        <div className="bg-white/5 rounded-3xl p-8 border border-white/10">
          <div className="flex items-center justify-between mb-8">
            <h2 className="text-2xl font-bold text-white">DEPARTMENT DISTRIBUTION</h2>
            <div className="text-white/50 text-sm">
              {calculatedStats.departments.length} active departments
            </div>
          </div>
          <div className="h-64">
            <Bar 
              data={departmentData()} 
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: {
                    display: false
                  }
                },
                scales: {
                  y: {
                    beginAtZero: true,
                    grid: {
                      color: 'rgba(255, 255, 255, 0.05)'
                    },
                    ticks: {
                      color: 'rgba(255, 255, 255, 0.5)'
                    }
                  },
                  x: {
                    grid: {
                      display: false
                    },
                    ticks: {
                      color: 'rgba(255, 255, 255, 0.5)'
                    }
                  }
                }
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default Statistics;
